using Microsoft.AspNetCore.Mvc;
public class HomeController:BaseController {private readonly RaceDayApiClient _api;public HomeController(RaceDayApiClient api)=>_api=api;public async Task<IActionResult> Index(string? type,string? location){var q="api/events";var args=new List<string>();if(!string.IsNullOrWhiteSpace(type))args.Add("type="+Uri.EscapeDataString(type));if(!string.IsNullOrWhiteSpace(location))args.Add("location="+Uri.EscapeDataString(location));if(args.Count>0)q+="?"+string.Join("&",args);var (data,error,ok)=await _api.Send<List<EventDto>>(HttpMethod.Get,q);ViewBag.Error=ok?null:error;return View(data??new());}public IActionResult Error()=>View();}
